# Task dictionary
tasks = {}

def add_task(task_name):
    """Add a task to the task list."""
    if task_name in tasks:
        print(f"Task '{task_name}' already exists.")
    else:
        tasks[task_name] = False
        print(f"Task '{task_name}' added!")

def remove_task(task_name):
    """Remove a task from the task list."""
    if task_name in tasks:
        del tasks[task_name]
        print(f"Task '{task_name}' removed.")
    else:
        print(f"Task '{task_name}' not found.")

def mark_completed(task_name):
    """Mark a task as completed."""
    if task_name in tasks:
        tasks[task_name] = True
        print(f"Task '{task_name}' marked as completed.")
    else:
        print(f"Task '{task_name}' not found.")

def show_tasks():
    """Display all tasks and their completion status."""
    for task, completed in tasks.items():
        print(f"{task}: {'completed' if completed else 'not completed'}")

# Main loop
while True:
    command = input("Enter a command (add, remove, mark, or show): ").lower()

    if command == "add":
        task_name = input("Enter task name: ")
        add_task(task_name)

    elif command == "remove":
        task_name = input("Enter task name: ")
        remove_task(task_name)

    elif command == "mark":
        task_name = input("Enter task name: ")
        mark_completed(task_name)

    elif command == "show":
        show_tasks()

    elif command == "quit":
        break

